        ["Jas|magic"] = new[] { "我们要怎样才能用爱打破咒语呢？我不知道...", "摩根向我们展示了他从女巫那里学到的一些魔法。", "摩根在向我们展示他从法师那儿学到的一些魔法。" },
        ["Jas|money"] = new[] { "但…但这很贵！ 你是怎么买到的？", "你从苏琪那里买了东西吗？她有时会出售一些很稀有的物品！" },
