        ["Jodi|fishing"] = new[] { "砂锅鱼总是很受欢迎。", "山姆！你进来帮我收拾下鱼好吗？", "啊，你好！你！进来！这是鱼的味道吗？" },
        ["Jodi|food"] = new[] { "山姆！进来帮我准备下晚饭好吗？", "啊，你好！你！进来！这是鱼的味道吗？", "但是，亲爱的……你走之前可是最爱吃的爆米花了。" },
