        ["Lewis|nature"] = new[] { "你好，你。我是来看看这个老旧花园的。", "放心，你。肯德拉和我正在草拟一份详尽的提案。", "啊，山顶巨石？我委托了克林特做一些炸药来处理这件事。" },
        ["Lewis|solitude"] = new[] { "好吧！大家安静下来！", "我在鹈鹕镇当了 20 多年的镇长！ 选举的时候，没一个人投我的反对票。我觉得那意味着我的工作做得很好。 我喜欢当镇长。" },
        ["Lewis|sport"] = new[] { "这里比我记忆中还要破旧。", "周末的时候大家看起来都比较开心，你不这么觉得吗？ 然而，我 7 天都在上班。" },
        ["Lewis|town"] = new[] { "请大家注意一下。", "好吧！大家安静下来！", "是的……我要告诉大家。" },
        ["Lewis|work"] = new[] { "我希望 农场上一切都好。我不想看到它干透了的样子。", "你，我很高兴你能住在星露谷。而且你在 农场取得了很大的进步！", "我在鹈鹕镇当了 20 多年的镇长！ 选举的时候，没一个人投我的反对票。我觉得那意味着我的工作做得很好。 我喜欢当镇长。" },
        ["Linus|art"] = new[] { "我得回帐篷把我钓到的鱼清理内脏。 今晚可以美餐一顿了。", "我具备生存所需的一切能力，甚至更多。如果你能学着去聆听，就能听见大自然发出的美妙旋律。", "这山谷……这山谷有一种神奇的感觉，就好像它在呼唤我。 在我去过的所有地方中，只有这里给我以家的感觉。我原本打算只在这里待一个星期…… 一个星期变成了几个月。 茂密的森林，温和的天气，群山的景色，丰富的野生食物，美丽的季节变换…… 我深知我想在此度尽余生。" },
        ["Linus|craft"] = new[] { "你能从树木中学到很多东西。 多和它们相处，它们也许就会告诉你它们的秘密。 安静地去吧，年轻人。", "谢谢，你。你让我担心了，……我以为你会邀请我和你一起搬去农场！ 你知道，我将你视作星露谷中最亲密的朋友……你从来没有试图“修正”我……你尊重我的生活方式，即使你无法理解。 我真的很感激。", "雷欧…… 我想让你跟我们一起回星露谷去。 那个地方可漂亮了……没这里暖和，但是生机盎然……而且我住的地方就在正中心！ 我通晓那边的地形地貌，以及江湖、树木、动物，还有好多…… 所以说……我也算是大自然的孩子，是同一类的。 不过，我年岁已老……我想要在走之前把我学到的东西都传授给一个人…… 雷欧……你愿意跟我们回去吗？" },
        ["Linus|family"] = new[] { "你好，雷欧……我叫莱纳斯。 我听说了你的事情，包括你的鹦鹉家庭。 真的很特别！", "我深知我的父母也会很高兴的。他们辛辛苦苦挣来的钱被用来改善成千上万人的生活。 而我呢？我这辈子从来没有这么快乐过。", "我们成为好朋友有一段时间了，你。我很高兴你搬来星露谷。 你的农场，还有山谷里的其他农场，对我们的社区产生了巨大的影响。 这不由得使我想起过去你爷爷经营 农场的日子。" },
        ["Linus|fishing"] = new[] { "好吧，我得回帐篷把我钓到的鱼清理内脏。 再见，你。", "我得回帐篷把我钓到的鱼清理内脏。 今晚可以美餐一顿了。", "瞧。你看见了吗？这是一种我特制的鱼饵。 这是最顶级的货色……连我自己都想吃！ 给，这是我的配方。" },
        ["Linus|food"] = new[] { "你真好，但是不用了，谢谢！我今天找东西吃的运气很好。", "瞧。你看见了吗？这是一种我特制的鱼饵。 这是最顶级的货色……连我自己都想吃！ 给，这是我的配方。", "'你觉得我做这些有什么问题吗？_当然，这样太恶心了。_也许，对我来说，这就是我的生活方式。我也没出什么毛病。我只吃看起来新鲜的东西。_没有。浪费食物本身就是可耻的。_谢谢你， 你。我知道你是个开明的人。我觉得自己做的挺好的。我没伤害任何人。 _当然。这是违法的。那是乔治的私有财产。_可我又不信什么“私有财产”。要不，你要我怎么做？我得靠这些食物活下来。有点爱心好吗。 _虽然没有，但是你应该找一份工作不能当个寄生虫。_ ……不是所有人都适应这个世界， 你。你不知道我是什么样的人。我不会伤害任何人，我只是想用自己的方式活下去。这错了吗？'" },
        ["Linus|friendship"] = new[] { "我一个人挺开心的。 我不需要新朋友。", "谢谢你是我的好朋友，你。 我很高兴你知道我来自哪里。", "但你对我真的很好。你是个非常特别的人。 我把你当作好朋友。" },
